void AShipManager::TogglePilot(){auto* P=Pilot(this);if(!P)return;if(!bPilot&&FVector::Dist2D(P->GetActorLocation(),FVector(300,0,0))>280)return;bPilot=!bPilot;ControlledDrone=-1;if(bPilot){if(P->IsTabletOpen())P->ToggleTablet();P->GetCharacterMovement()->StopMovementImmediately();P->GetCharacterMovement()->DisableMovement();P->SetActorLocation(FVector(340,0,96));if(P->Controller)P->Controller->SetControlRotation(FRotator::ZeroRotator);}else{P->GetCharacterMovement()->SetMovementMode(MOVE_Walking);P->SetActorLocation(FVector(100,0,96));}SetCamera(0);}
bool AShipManager::AtExchange()const{auto* P=Pilot(this);auto* E=Expedition();return P&&E&&E->State.onStation&&P->GetActorLocation().Y>1000&&FMath::Abs(P->GetActorLocation().X+6000)<400;}
void AShipManager::BoardStation(){auto* P=Pilot(this);auto* E=Expedition();if(!P||!E||!E->Command(HelioExplore::Command::Board))return;bPilot=false;ControlledDrone=-1;P->GetCharacterMovement()->SetMovementMode(MOVE_Walking);P->SetActorLocation(FVector(-6000,-1400,96));if(P->Controller)P->Controller->SetControlRotation(FRotator(0,90,0));SetCamera(0);if(P->IsTabletOpen())P->ToggleTablet();}
void AShipManager::ReturnToShip(){auto* P=Pilot(this);auto* E=Expedition();if(!P||!E||!E->State.onStation||P->GetActorLocation().Y> -1100)return;if(!E->Command(HelioExplore::Command::Return))return;P->SetActorLocation(FVector(-250,0,96));if(P->Controller)P->Controller->SetControlRotation(FRotator::ZeroRotator);if(P->IsTabletOpen())P->ToggleTablet();}
void AShipManager::Repair(int R){if(R>=0&&R<4){Venting[R]=false;Breach[R]=false;}}
void AShipManager::SetHazard(int R,bool Thermal){if(R>=0&&R<4){if(Thermal)Venting[R]=true;else Breach[R]=true;}}
void AShipManager::ControlDrone(int I){if(I<0||I>=3||DroneHealth[I]<=0)return;ControlledDrone=I;bPilot=false;SetCamera(0);if(auto* P=Pilot(this))if(P->IsTabletOpen())P->ToggleTablet();if(auto* PC=UGameplayStatics::GetPlayerController(this,0))PC->SetViewTargetWithBlend(DroneCamera,.3f);}
void AShipManager::DamageDrone(int I,float D){if(I<0||I>=3)return;DroneHealth[I]=FMath::Max(0.f,DroneHealth[I]-D);if(DroneHealth[I]<=0&&ControlledDrone==I){ControlledDrone=-1;StaticTime=2;SetCamera(0);}}
